import { Component, OnInit, signal } from '@angular/core';
import { DevotionalEventPlanner } from '../../../services/devotional-event-planner';
import { DevotionalScheduleEventItem } from '../devotional-schedule-event-item/devotional-schedule-event-item';
import { CommonFooter } from '../../../../utils/components/common-footer/common-footer';

@Component({
  selector: 'devotional-event-planner-main',
  imports: [DevotionalScheduleEventItem, CommonFooter],
  templateUrl: './devotional-event-planner-main.html',
  styleUrl: './devotional-event-planner-main.css',
})
export class DevotionalEventPlannerMain implements OnInit {

  isLoading = signal<boolean>(false);

  scheduledEvents!: Array<any>;

  constructor(
    private readonly _eventPlanner: DevotionalEventPlanner
  ) { }

  ngOnInit(): void {
    this.isLoading.set(true);
    this._eventPlanner.getScheduledEvents().subscribe(d => {
      this.scheduledEvents = d; 
      this.isLoading.set(false);
    })
  }

}
