import { HttpClient } from '@angular/common/http';
import { inject, Injectable } from '@angular/core';
import { catchError, Observable, of, tap } from 'rxjs';

@Injectable({
  providedIn: 'root',
})
export class DevotionalEventPlanner {

  private readonly _http = inject(HttpClient);
  private _scheduledEvent: any;
  private readonly _itemUrl: string = 'events/';

  getScheduledEvents() {

    if (this._scheduledEvent) {
      return of(this._scheduledEvent)
    } else {
      return this._http.get<Object[]>(this._itemUrl + 'event-list.json')
        .pipe(
          tap((data) => {
            this._scheduledEvent = data.map(e => this.addAdditionalKeys(e));
          }),
          catchError(this.handleError('error with getting module info', []))
        )
    }
  }

  getAiPanditData(str: string): Observable<{language:Array<object>, english:object, hindi:object}>{

    return this._http.get<{language:Array<object>, english:object, hindi:object}>(this._itemUrl + str + '.json').pipe(
      tap((data) => { }),
      catchError(this.handleError('error with getting module info', {language:[], english:{}, hindi:{}}))
    )

  }


  private addAdditionalKeys(data: any): boolean {
    const parts = data.date.split('-');
    const day = parseInt(parts[0], 10);
    const month = parseInt(parts[1], 10) - 1;
    const year = parseInt(parts[2], 10);
    const schedule = new Date(year, month, day)
    const now = new Date();
    return {
      ...data, ...{
        findished: schedule < now,
        remaining: Math.floor((schedule.getTime() - now.getTime()) / (1000 * 60 * 60 * 24))//schedule.getDate() - now.getDate()
      }
    };

  }

  /**
   * Handle Http operation that failed.
   * Let the app continue.
   * @param operation - name of the operation that failed
   * @param result - optional value to return as the observable result
   */
  private handleError<T>(operation = 'operation', result?: T) {
    return (error: any): Observable<T> => {

      // TODO: send the error to remote logging infrastructure
      console.error(error); // log to console instead

      // TODO: better job of transforming error for user consumption
      console.log(`${operation} failed: ${error.message}`);

      // Let the app keep running by returning an empty result.
      return of(result as T);
    };
  }

}
